        for cmd in cmds:
            try:
                results[cmd] = conn.send_command(cmd, read_timeout=15)
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
        return name, results
    except Exception as e:
        return name, {"CONNECTION_ERROR": traceback.format_exc()}

