#!/usr/bin/env python3
"""Final verification of the lab against the definition of done."""

from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler
import json, time

DEVICES = {
    "HQ-Edge": {"host": "192.168.122.11", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Hub-A":   {"host": "192.168.122.12", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Hub-B":   {"host": "192.168.122.13", "device_type": "vyos", "username": "vyos", "password": "test"},
}
MIKROTIK = {
    "Branch-1": {"host": "192.168.122.21", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-2": {"host": "192.168.122.22", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-3": {"host": "192.168.122.23", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-4": {"host": "192.168.122.24", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
}
HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.1.10"},
    "B1-PC2": {"host": "192.168.122.32", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.1.11"},
    "B2-PC1": {"host": "192.168.122.33", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.2.10"},
    "B2-PC2": {"host": "192.168.122.34", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.2.11"},
    "B3-PC1": {"host": "192.168.122.35", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.3.10"},
    "B3-PC2": {"host": "192.168.122.36", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.1.3.11"},
    "B4-PC1": {"host": "192.168.122.37", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.1.10"},
    "B4-PC2": {"host": "192.168.122.38", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.1.11"},
    "B4-PC3": {"host": "192.168.122.39", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.2.10"},
    "B4-PC4": {"host": "192.168.122.40", "device_type": "linux", "username": "root", "password": "alpine", "lab_ip": "10.2.2.11"},
}

GUEST_HOSTS = {"B4-PC3", "B4-PC4"}
NON_GUEST_HOSTS = set(HOSTS.keys()) - GUEST_HOSTS

def collect_router_state():
    """Collect adjacencies, routes, BGP from all routers."""
    results = {}

    def do_vyos(name, params):
        conn = ConnectHandler(**params)
        r = {}
        cmds = ["show ip ospf neighbor", "show ip route"]
        if name == "HQ-Edge":
            cmds += ["show ip bgp", "show ip bgp neighbors 203.0.113.1 advertised-routes",
                     "show ip bgp neighbors 203.0.113.5 advertised-routes",
                     "show configuration commands | grep ospf",
                     "show configuration commands | grep nat",
                     "show configuration commands | grep route-map"]
        for cmd in cmds:
            r[cmd] = conn.send_command(cmd, read_timeout=30)
        conn.disconnect()
        return name, r

    def do_mt(name, params):
        conn = ConnectHandler(**params)
        r = {}
        for cmd in ["/routing ospf neighbor print detail", "/ip route print terse"]:
            r[cmd] = conn.send_command(cmd, read_timeout=30)
        conn.disconnect()
        return name, r

    with ThreadPoolExecutor(max_workers=7) as ex:
        futs = []
        for n, p in DEVICES.items():
            futs.append(ex.submit(do_vyos, n, p))
        for n, p in MIKROTIK.items():
            futs.append(ex.submit(do_mt, n, p))
        for f in as_completed(futs):
            name, r = f.result()
            results[name] = r
    return results

def ping_test_host(host_name, targets):
    """From one host, ping a list of targets. Returns dict of target->pass/fail."""
    params = {k: v for k, v in HOSTS[host_name].items() if k != "lab_ip"}
    conn = ConnectHandler(**params)
    results = {}
    for t_name, t_ip in targets:
        out = conn.send_command(f"ping -c 2 -W 3 {t_ip}", read_timeout=15)
        success = "bytes from" in out or " 0% packet loss" in out
        results[(host_name, t_name, t_ip)] = success
    conn.disconnect()
    return results

def run_host_pings():
    """Run all host-to-host and host-to-internet pings in parallel."""
    all_results = {}
    all_host_ips = [(n, HOSTS[n]["lab_ip"]) for n in HOSTS]
    internet_targets = [("8.8.8.8", "8.8.8.8"), ("1.1.1.1", "1.1.1.1")]

    with ThreadPoolExecutor(max_workers=10) as ex:
        futs = []
        for src in HOSTS:
            targets = []
            for dst_name, dst_ip in all_host_ips:
                if dst_name != src:
                    targets.append((dst_name, HOSTS[dst_name]["lab_ip"]))
            targets += internet_targets
            futs.append(ex.submit(ping_test_host, src, targets))
        for f in as_completed(futs):
            all_results.update(f.result())
    return all_results

def main():
    print("=" * 60)
    print("COLLECTING ROUTER STATE")
    print("=" * 60)
    rstate = collect_router_state()

    for name in ["HQ-Edge", "Hub-A", "Hub-B", "Branch-1", "Branch-2", "Branch-3", "Branch-4"]:
        print(f"\n--- {name} ---")
